CREATE TABLE IF NOT EXISTS `connections` (`id` text,`user_id` integer,`channel` text,`name` text,`settings_json` JSON,`secret_json` JSON,`status` text,`last_verified_at` integer,`last_error_code` text,`last_error_message` text,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_connections_user_channel` ON `connections`(`user_id`,`channel`);
CREATE TABLE IF NOT EXISTS `workflows` (`id` text,`user_id` integer,`name` text,`connection_json` JSON,`secret_json` JSON,`target_json` JSON,`schedule_enabled` numeric,`interval_minutes` integer,`include_attachments` numeric,`status` text,`last_sync_at` integer,`next_sync_at` integer,`last_error` text,`synced_messages` integer,`cursor_uid_validity` integer,`cursor_uid` integer,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_workflows_status` ON `workflows`(`status`);
CREATE INDEX IF NOT EXISTS `idx_email_sync_due` ON `workflows`(`schedule_enabled`,`next_sync_at`);
CREATE INDEX IF NOT EXISTS `idx_email_sync_user` ON `workflows`(`user_id`);
CREATE TABLE IF NOT EXISTS `sync_items` (`id` integer PRIMARY KEY AUTOINCREMENT,`workflow_id` text,`mailbox` text,`uid_validity` integer,`uid` integer,`document_path` text,`status` text,`last_error` text,`completed_at` integer,`created_at` integer,`updated_at` integer);
CREATE INDEX IF NOT EXISTS `idx_sync_items_completed_at` ON `sync_items`(`completed_at`);
CREATE INDEX IF NOT EXISTS `idx_sync_items_status` ON `sync_items`(`status`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_email_sync_item_identity` ON `sync_items`(`workflow_id`,`mailbox`,`uid_validity`,`uid`);
CREATE TABLE IF NOT EXISTS `sync_runs` (`id` text,`workflow_id` text,`user_id` integer,`mode` text,`status` text,`discovered_messages` integer,`processed_messages` integer,`imported` integer,`updated` integer,`skipped` integer,`failed` integer,`current_batch` integer,`table_path` text,`error` text,`cancel_requested` numeric,`started_at` integer,`finished_at` integer,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_email_sync_run_status` ON `sync_runs`(`status`);
CREATE INDEX IF NOT EXISTS `idx_email_sync_run_user` ON `sync_runs`(`user_id`);
CREATE INDEX IF NOT EXISTS `idx_email_sync_run_workflow` ON `sync_runs`(`workflow_id`);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (workspace TEXT NOT NULL, path TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(workspace,path));
CREATE TABLE IF NOT EXISTS sent_receipts (workspace TEXT NOT NULL, path TEXT NOT NULL, message_id TEXT NOT NULL, status TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(workspace,path));
CREATE TABLE IF NOT EXISTS agent_sessions (id TEXT PRIMARY KEY, workspace TEXT NOT NULL, contact TEXT, agent TEXT NOT NULL, status TEXT NOT NULL, transcript TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_queue (workspace TEXT NOT NULL, contact TEXT NOT NULL, reason TEXT NOT NULL, due INTEGER NOT NULL, PRIMARY KEY(workspace,contact));
CREATE TABLE IF NOT EXISTS terminals (id TEXT PRIMARY KEY, workspace TEXT NOT NULL, agent TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, cols INTEGER NOT NULL, rows INTEGER NOT NULL, error TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_terminal_workspace ON terminals(workspace,created_at);
CREATE TABLE IF NOT EXISTS terminal_output (session TEXT NOT NULL, seq INTEGER NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(session,seq));
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, workspace TEXT NOT NULL, source_key TEXT NOT NULL, name TEXT NOT NULL, base_url TEXT NOT NULL, header TEXT NOT NULL, secret TEXT NOT NULL, manifest TEXT NOT NULL, interval_minutes INTEGER NOT NULL DEFAULT 60, next_sync_at INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(workspace, source_key));
CREATE TABLE IF NOT EXISTS source_cursors (source TEXT NOT NULL, stream TEXT NOT NULL, cursor TEXT NOT NULL, PRIMARY KEY(source, stream));
CREATE TABLE IF NOT EXISTS source_runs (id TEXT PRIMARY KEY, source TEXT NOT NULL, status TEXT NOT NULL, people INTEGER NOT NULL DEFAULT 0, events INTEGER NOT NULL DEFAULT 0, linked INTEGER NOT NULL DEFAULT 0, pending INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', started_at INTEGER NOT NULL, finished_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_source_runs ON source_runs(source, started_at);
CREATE TABLE IF NOT EXISTS list_items (workspace TEXT NOT NULL, list TEXT NOT NULL, member TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', contact TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, session TEXT NOT NULL DEFAULT '', draft TEXT NOT NULL DEFAULT '', evidence TEXT NOT NULL DEFAULT '[]', error TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL, PRIMARY KEY(workspace, list, member));
CREATE TABLE IF NOT EXISTS outreach_sends (workspace TEXT NOT NULL, path TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(workspace, path));
CREATE TABLE IF NOT EXISTS agent_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace TEXT NOT NULL, session TEXT NOT NULL DEFAULT '', tool TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', target TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', ok INTEGER NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_agent_activity ON agent_activity(workspace,session,id);
